var RC_MAP = [
  "111111111111",
  "1..........1",
  "1..22..33..1",
  "1..2....3..1",
  "1..........1",
  "1..4....5..1",
  "1..44..55..1",
  "1..........1",
  "111111111111"
];
function rcCell(map, x, y){
  var r = map[Math.floor(y)];
  if(r === undefined) return 1;
  var c = r[Math.floor(x)];
  if(c === undefined || c === '1') return 1;
  return c === '.' ? 0 : Number(c);
}
function rcCast(map, px, py, ang){
  var dx = Math.cos(ang), dy = Math.sin(ang);
  var mapX = Math.floor(px), mapY = Math.floor(py);
  var ddx = dx === 0 ? 1e30 : Math.abs(1/dx), ddy = dy === 0 ? 1e30 : Math.abs(1/dy);
  var stepX = dx < 0 ? -1 : 1, stepY = dy < 0 ? -1 : 1;
  var sdx = dx < 0 ? (px - mapX) * ddx : (mapX + 1 - px) * ddx;
  var sdy = dy < 0 ? (py - mapY) * ddy : (mapY + 1 - py) * ddy;
  var side = 0, tile = 0;
  for(var i=0;i<64;i++){
    if(sdx < sdy){ sdx += ddx; mapX += stepX; side = 0; }
    else { sdy += ddy; mapY += stepY; side = 1; }
    tile = rcCell(map, mapX + 0.5, mapY + 0.5);
    if(tile > 0) break;
  }
  var dist = side === 0 ? sdx - ddx : sdy - ddy;
  return { dist: Math.max(dist, 1e-6), side: side, tile: tile };
}
function rcFrame(map, px, py, ang, w, fov){
  var cols = [];
  for(var x=0;x<w;x++){
    var ra = ang + (x/w - 0.5) * fov;
    var hit = rcCast(map, px, py, ra);
    var corr = hit.dist * Math.cos(ra - ang);
    cols.push({ h: 1/Math.max(corr, 1e-6), side: hit.side, tile: hit.tile });
  }
  return cols;
}
function rcMove(map, px, py, ang, forward){
  var nx = px + Math.cos(ang) * 0.2 * forward;
  var ny = py + Math.sin(ang) * 0.2 * forward;
  if(rcCell(map, nx, py) === 0) px = nx;
  if(rcCell(map, px, ny) === 0) py = ny;
  return { x: px, y: py };
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { RC_MAP:RC_MAP, rcCell:rcCell, rcCast:rcCast, rcFrame:rcFrame, rcMove:rcMove };
}
if (typeof window !== 'undefined') {
  window.RaycastForgePure = { RC_MAP:RC_MAP, rcCell:rcCell, rcCast:rcCast, rcFrame:rcFrame, rcMove:rcMove };
}
